DROP TABLE IF EXISTS `commission_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `commission_transactions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `transaction_code` varchar(50) NOT NULL,
  `franchise_id` int(11) NOT NULL,
  `customer_id` int(11) DEFAULT NULL,
  `service_id` int(11) DEFAULT NULL,
  `case_id` int(11) DEFAULT NULL,
  `gross_amount` decimal(12,2) NOT NULL,
  `govt_fee` decimal(10,2) DEFAULT 0.00,
  `prof_fee` decimal(10,2) DEFAULT 0.00,
  `commission_type` enum('fixed','percentage') DEFAULT 'fixed',
  `commission_rate` decimal(10,2) DEFAULT 0.00,
  `commission_amount` decimal(10,2) NOT NULL,
  `tds_amount` decimal(10,2) DEFAULT 0.00,
  `net_commission` decimal(10,2) NOT NULL,
  `status` enum('pending','approved','available','paid','reversed') DEFAULT 'pending',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaction_code` (`transaction_code`),
  KEY `franchise_id` (`franchise_id`),
  KEY `customer_id` (`customer_id`),
  KEY `service_id` (`service_id`),
  KEY `case_id` (`case_id`),
  CONSTRAINT `commission_transactions_ibfk_1` FOREIGN KEY (`franchise_id`) REFERENCES `franchises` (`id`) ON DELETE CASCADE,
  CONSTRAINT `commission_transactions_ibfk_2` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `commission_transactions_ibfk_3` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE SET NULL,
  CONSTRAINT `commission_transactions_ibfk_4` FOREIGN KEY (`case_id`) REFERENCES `cases` (`id`) ON DELETE SET NULL
