  `category_id` int(11) NOT NULL,
  `subcategory_id` int(11) DEFAULT NULL,
  `name` varchar(200) NOT NULL,
  `slug` varchar(200) NOT NULL,
  `short_description` text DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `featured_image` varchar(255) DEFAULT NULL,
  `icon` varchar(100) DEFAULT 'bi-gear',
  `govt_fee` decimal(10,2) DEFAULT 0.00,
  `prof_fee` decimal(10,2) DEFAULT 0.00,
  `gst_rate` decimal(5,2) DEFAULT 18.00,
  `final_price` decimal(10,2) DEFAULT 0.00,
  `franchise_price` decimal(10,2) DEFAULT 0.00,
  `franchise_commission_type` enum('fixed','percentage') DEFAULT 'fixed',
  `franchise_commission_value` decimal(10,2) DEFAULT 0.00,
  `processing_time` varchar(100) DEFAULT '3-5 Business Days',
  `required_docs` text DEFAULT NULL,
  `eligibility` text DEFAULT NULL,
  `faq_json` longtext DEFAULT NULL,
  `terms` text DEFAULT NULL,
  `is_payment_required` tinyint(1) DEFAULT 1,
  `payment_timing` enum('upfront','post_approval','split') DEFAULT 'upfront',
  `assigned_department` varchar(100) DEFAULT 'General',
  `is_featured` tinyint(1) DEFAULT 0,
  `seo_title` varchar(255) DEFAULT NULL,
  `seo_description` text DEFAULT NULL,
  `status` enum('active','inactive') DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `service_code` varchar(50) DEFAULT NULL,
  `other_charges` decimal(10,2) DEFAULT 0.00,
  `is_gst_applicable` tinyint(1) DEFAULT 1,
  `is_discount_allowed` tinyint(1) DEFAULT 1,
  `expected_completion_time` varchar(100) DEFAULT '3-5 Working Days',
  `min_time` int(11) DEFAULT 1,
  `max_time` int(11) DEFAULT 7,
  `time_unit` enum('Hours','Days','Working Days') DEFAULT 'Working Days',
  `important_notes` text DEFAULT NULL,
  `display_order` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `category_id` (`category_id`),
  CONSTRAINT `services_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `service_categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

